
import React, { useMemo, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import Footer from "./Footer";

const clinics = [
  {
    id: 1,
    name: "Afghan Health Clinic",
    area: "AbdulHaq Square",
    city: "Kabul, Afghanistan",
    phone: "+93 786 504 921",
    specialty: "Primary Care",
    image: "/images/area1.jpg",
  },
  {
    id: 2,
    name: "Salar Clinic",
    area: "Karti 4",
    city: "Kabul, Afghanistan",
    phone: "+93 765 650 4921",
    specialty: "General Medicine",
    image: "/images/area2.jpg",
  },
];

function FindClinicList() {
  const location = useLocation();
  const navigate = useNavigate();

  const params = new URLSearchParams(location.search);

  const [query, setQuery] = useState(params.get("q") || "");
  const [area, setArea] = useState(params.get("area") || "");
  const [specialty, setSpecialty] = useState("");

  // Filter clinics according to the search and selected filters.
  const filtered = useMemo(
    () =>
      clinics.filter(
        (clinic) =>
          `${clinic.name} ${clinic.area} ${clinic.city} ${clinic.specialty}`
            .toLowerCase()
            .includes(query.toLowerCase()) &&
          `${clinic.area} ${clinic.city}`
            .toLowerCase()
            .includes(area.toLowerCase()) &&
          (!specialty || clinic.specialty === specialty)
      ),
    [query, area, specialty]
  );

  return (
    <div className="discovery-page">
      {/* Page Banner */}
      <section className="doctor-banner">
        <h1>Clinic List</h1>
        <p>Browse clinics and medical centers.</p>

        <div className="banner-search">
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Clinic or specialty"
          />

          <input
            value={area}
            onChange={(e) => setArea(e.target.value)}
            placeholder="City or neighborhood"
          />

          <button
            type="button"
            onClick={() => {
              setQuery("");
              setArea("");
              setSpecialty("");
            }}
          >
            Clear
          </button>
        </div>
      </section>

      {/* Navigation Buttons */}
      <div className="view-buttons">
        <Link to="/findclinic" className="view-btn">
          Overview
        </Link>

        <Link
          to="/findcliniclist"
          className="view-btn active-btn"
        >
          <i className="fa-solid fa-list" /> List
        </Link>

        <Link to="/findclinicmap" className="view-btn">
          <i className="fa-solid fa-map" /> Map
        </Link>
      </div>

      {/* Clinic Results */}
      <section className="service-section">
        <label>
          Specialty{" "}
          <select
            value={specialty}
            onChange={(e) => setSpecialty(e.target.value)}
          >
            <option value="">All specialties</option>
            <option>Primary Care</option>
            <option>General Medicine</option>
          </select>
        </label>

        <h2>
          {filtered.length} clinic
          {filtered.length === 1 ? "" : "s"} found
        </h2>

        {filtered.length > 0 ? (
          filtered.map((clinic) => (
            <article className="clinic-card" key={clinic.id}>
              <img src={clinic.image} alt={clinic.name} />

              <div className="clinic-info">
                <h3>{clinic.name}</h3>

                <p>
                  {clinic.area}, {clinic.city}
                </p>

                <p>{clinic.specialty}</p>

                <p>{clinic.phone}</p>
              </div>

              {/* Clinic Actions */}
              <div className="clinic-buttons">
                <button
                  type="button"
                  onClick={() =>
                    navigate(
                      `/findclinicmap?q=${encodeURIComponent(
                        clinic.name
                      )}`
                    )
                  }
                >
                  View on map
                </button>

                <button
                  type="button"
                  onClick={() => navigate("/finddoctor")}
                >
                  Find a doctor
                </button>
              </div>
            </article>
          ))
        ) : (
          <p>
            No clinics match your filters. Clear the filters or try a
            different search.
          </p>
        )}
      </section>

      {/* Footer */}
      <Footer />
    </div>
  );
}

export default FindClinicList;
